1	import {createChatOrchestrator} from './chatOrchestrator.js';
2	import type {OrchestratorHooks} from './chatOrchestrator.js';
3	import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
4	import {AIError} from '../types/ai.js';
5	import type {ChatSession} from '../types/session.js';
6	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
7	import {ToolRegistry} from './tools/registry.js';
8	import type {ToolResponse} from './tools/registry.js';
9	import type {OutgoingMessage} from '../types/messages.js';
10	import type {SessionEntry} from '../types/session.js';
11	
12	// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
13	const SENT_AT = '2026-01-01T00:00:00.000Z';
14	
15	// One expect per test needs the rejection as a value rather than a matcher.
16	const outcomeOf = (call: Promise<unknown>): Promise<string> =>
17	  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);
18	
19	function createSession(content: string): ChatSession {
20	  return {
21	    sessionId: 's1',
22	    userId: 'u1',
23	    entries: [{role: 'user', content, timestamp: SENT_AT}],
24	  };
25	}
26	
27	function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
28	  return {
29	    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
30	      yield {type: 'text', text: response};
31	      yield {type: 'stop', stopReason: 'end_turn', usage};
32	    },
33	    async generateStructured<T>(): Promise<T> {
34	      return {} as T;
35	    },
36	  };
37	}
38	
39	function createErrorProvider(error: Error): AIProvider {
40	  return {
41	    // eslint-disable-next-line require-yield
42	    async *sendMessage(): AsyncGenerator<MessageChunk> {
43	      throw error;
44	    },
45	    async generateStructured<T>(): Promise<T> {
46	      return {} as T;
47	    },
48	  };
49	}
50	
51	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
52	
53	type RecordedHook =
54	  | 'beforeSession'
55	  | 'beforeUserInput'
56	  | 'afterUserInput'
57	  | 'beforeModelResponse'
58	  | 'afterModelResponse'
59	  | 'afterSession'
60	  | 'onError';
61	
62	// Only the named hooks are installed: one that merely exists changes the observed order.
63	const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
64	  const all: Required<Pick<OrchestratorHooks, RecordedHook>> = {
65	    beforeSession: async () => void callOrder.push('beforeSession'),
66	    beforeUserInput: async (_session, msg) => {
67	      callOrder.push('beforeUserInput');
68	      return msg;
69	    },
70	    afterUserInput: async () => void callOrder.push('afterUserInput'),
71	    beforeModelResponse: async (_session, systemPrompt) => {
72	      callOrder.push('beforeModelResponse');
73	      return systemPrompt;
74	    },
75	    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
76	    afterSession: async () => void callOrder.push('afterSession'),
77	    onError: async () => void callOrder.push('onError'),
78	  };
79	
80	  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
81	};
82	
83	// Records what the orchestrator actually sent, for tests that assert on the request.
84	const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
85	  const sent = {systemPrompt: '', lastUserContent: ''};
86	
87	  return {
88	    sent,
89	    provider: {
90	      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
91	        sent.systemPrompt = params.systemPrompt;
92	        const last = params.messages[params.messages.length - 1];
93	        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
94	        yield {type: 'text', text: 'ok'};
95	        yield {type: 'stop', stopReason: 'end_turn'};
96	      },
97	      async generateStructured<T>(): Promise<T> {
98	        return {} as T;
99	      },
100	    },
101	  };
102	};
103	
104	describe('ChatOrchestrator hooks', () => {
105	  describe('beforeSession', () => {
106	    it('called before anything else', async () => {
107	      const callOrder: string[] = [];
108	      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);
109	
110	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
111	      await orchestrator.processMessage(createSession('hello'));
112	
113	      expect(callOrder[0]).toBe('beforeSession');
114	    });
115	
116	    it('runs onError then afterSession when it throws, and still rejects to the caller', async () => {
117	      const callOrder: string[] = [];
118	      let onErrorMessage: string | undefined;
119	      const hooks: OrchestratorHooks = {
120	        beforeSession: async () => {
121	          callOrder.push('beforeSession');
122	          throw new Error('beforeSession boom');
123	        },
124	        onError: async (_session, error) => {
125	          callOrder.push('onError');
126	          onErrorMessage = error.message;
127	        },
128	        afterSession: async () => {
129	          callOrder.push('afterSession');
130	        },
131	      };
132	
133	      const orchestrator = createChatOrchestrator(createMockProvider('never'), promptBuilder, undefined, {hooks});
134	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
135	
136	      expect({outcome, onErrorMessage, callOrder}).toEqual({
137	        outcome: 'beforeSession boom',
138	        onErrorMessage: 'beforeSession boom',
139	        callOrder: ['beforeSession', 'onError', 'afterSession'],
140	      });
141	    });
142	  });
143	
144	  describe('afterSession', () => {
145	    it('called after everything completes', async () => {
146	      const callOrder: string[] = [];
147	      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);
148	
149	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
150	      await orchestrator.processMessage(createSession('hello'));
151	
152	      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
153	    });
154	
155	    it('called even when an error occurs', async () => {
156	      let afterSessionCalled = false;
157	      const hooks: OrchestratorHooks = {
158	        onError: async () => {},
159	        afterSession: async () => {
160	          afterSessionCalled = true;
161	        },
162	      };
163	
164	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
165	        hooks,
166	      });
167	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
168	
169	      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
170	    });
171	  });
172	
173	  describe('beforeUserInput', () => {
174	    it('receives the last user message content', async () => {
175	      let receivedMessage = '';
176	      const hooks: OrchestratorHooks = {
177	        beforeUserInput: async (_session, userMessage) => {
178	          receivedMessage = userMessage;
179	          return userMessage;
180	        },
181	      };
182	
183	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
184	      await orchestrator.processMessage(createSession('my answer'));
185	
186	      expect(receivedMessage).toBe('my answer');
187	    });
188	
189	    it('modifies user message when returning different value', async () => {
190	      const {provider, sent} = capturingProvider();
191	
192	      const hooks: OrchestratorHooks = {
193	        beforeUserInput: async (_session, _msg) => 'sanitized input',
194	      };
195	
196	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
197	      await orchestrator.processMessage(createSession('raw input'));
198	
199	      expect(sent.lastUserContent).toBe('sanitized input');
200	    });
201	  });
202	
203	  describe('afterUserInput', () => {
204	    it('receives user message after any beforeUserInput modification', async () => {
205	      let afterReceived = '';
206	      const hooks: OrchestratorHooks = {
207	        beforeUserInput: async (_s, _msg) => 'modified',
208	        afterUserInput: async (_s, msg) => {
209	          afterReceived = msg;
210	        },
211	      };
212	
213	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
214	      await orchestrator.processMessage(createSession('original'));
215	
216	      expect(afterReceived).toBe('modified');
217	    });
218	  });
219	
220	  describe('beforeModelResponse', () => {
221	    it('replaces system prompt with returned value', async () => {
222	      const {provider, sent} = capturingProvider();
223	
224	      const hooks: OrchestratorHooks = {
225	        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
226	      };
227	
228	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
229	      await orchestrator.processMessage(createSession('hello'));
230	
231	      expect(sent.systemPrompt).toBe('Custom prompt for this question');
232	    });
233	  });
234	
235	  describe('afterModelResponse', () => {
236	    it('receives collected response text and usage', async () => {
237	      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
238	      let receivedText = '';
239	      let receivedUsage: UsageMetadata | undefined;
240	
241	      const hooks: OrchestratorHooks = {
242	        afterModelResponse: async (_session, text, u) => {
243	          receivedText = text;
244	          receivedUsage = u;
245	        },
246	      };
247	
248	      const orchestrator = createChatOrchestrator(createMockProvider('hello world', usage), promptBuilder, undefined, {
249	        hooks,
250	      });
251	      await orchestrator.processMessage(createSession('hi'));
252	
253	      expect({receivedText, receivedUsage}).toEqual({receivedText: 'hello world', receivedUsage: usage});
254	    });
255	
256	    it('not called when stream throws', async () => {
257	      let afterCalled = false;
258	      const hooks: OrchestratorHooks = {
259	        afterModelResponse: async () => {
260	          afterCalled = true;
261	        },
262	        onError: async () => {},
263	      };
264	
265	      const orchestrator = createChatOrchestrator(
266	        createErrorProvider(new AIError('fail', 'TEST')),
267	        promptBuilder,
268	        undefined,
269	        {hooks}
270	      );
271	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
272	
273	      expect({outcome, afterCalled}).toEqual({outcome: 'fail', afterCalled: false});
274	    });
275	  });
276	
277	  describe('onError', () => {
278	    it('called with session and error when stream fails', async () => {
279	      let receivedError: Error | undefined;
280	      const hooks: OrchestratorHooks = {
281	        onError: async (_session, error) => {
282	          receivedError = error;
283	        },
284	      };
285	
286	      const orchestrator = createChatOrchestrator(
287	        createErrorProvider(new AIError('rate limited', 'RATE_LIMITED')),
288	        promptBuilder,
289	        undefined,
290	        {hooks}
291	      );
292	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
293	
294	      expect({outcome, receivedErrorMessage: receivedError?.message}).toEqual({
295	        outcome: 'rate limited',
296	        receivedErrorMessage: 'rate limited',
297	      });
298	    });
299	
300	    it('error still propagates after onError hook', async () => {
301	      const hooks: OrchestratorHooks = {
302	        onError: async () => {},
303	      };
304	
305	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
306	        hooks,
307	      });
308	      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
309	    });
310	  });
311	
312	  describe('full lifecycle order', () => {
313	    it('calls all hooks in correct order', async () => {
314	      const callOrder: string[] = [];
315	      const usage: UsageMetadata = {inputTokens: 5, outputTokens: 3, totalTokens: 8};
316	
317	      const hooks: OrchestratorHooks = {
318	        beforeSession: async () => {
319	          callOrder.push('beforeSession');
320	        },
321	        beforeUserInput: async (_s, msg) => {
322	          callOrder.push('beforeUserInput');
323	          return msg;
324	        },
325	        afterUserInput: async () => {
326	          callOrder.push('afterUserInput');
327	        },
328	        beforeModelResponse: async (_s, p) => {
329	          callOrder.push('beforeModelResponse');
330	          return p;
331	        },
332	        afterModelResponse: async () => {
333	          callOrder.push('afterModelResponse');
334	        },
